graphAndPostPins.command:
node --input-type=module <<'NODE'
import fs from 'node:fs';
import {createHash} from 'node:crypto';
import {build} from 'esbuild';
const h=v=>createHash('sha256').update(v).digest('hex');
const w=JSON.parse(fs.readFileSync('docs/remediation/evidence/W05.04/artifact-v1.json','utf8'));
const a=w.artifact, pins=new Map(a.files.map(f=>[f.path,f.sha256]));
const options={...w.options,entryPoints:w.entryPoints,metafile:true,outdir:'/tmp/w0504-review-write-false',logLevel:'silent'};
const b=await build(options);
const inputs=Object.keys(b.metafile.inputs).sort();
const uncovered=inputs.filter(p=>!pins.has(p));
const mismatches=a.files.flatMap(f=>{const actual=h(fs.readFileSync(f.path));return actual===f.sha256?[]:[{path:f.path,actual,expected:f.sha256}]});
const originals=JSON.parse(fs.readFileSync('docs/remediation/evidence/W05.04/before-sources-v1.json','utf8'));
const originalCheck=originals.files.map(f=>({path:f.path,expected:f.sha256,actual:h(f.content),current:h(fs.readFileSync(f.path))}));
const old=JSON.parse(fs.readFileSync('docs/remediation/evidence/W05.03/artifact-v1.json','utf8')).artifact;
const originalPaths=new Set(originals.files.map(f=>f.path));
const protectedDrift=old.files.filter(f=>!originalPaths.has(f.path)).flatMap(f=>h(fs.readFileSync(f.path))===f.sha256?[]:[f.path]);
const originalBoundary=originals.files.find(f=>f.path==='src/routes/realtime.sdkContract.test.ts').content;
const currentBoundary=fs.readFileSync('src/routes/realtime.sdkContract.test.ts','utf8');
const priorTail="describe('W05.03 consent-safe product sorting'";
const tailUnchanged=currentBoundary.slice(currentBoundary.indexOf(priorTail))===originalBoundary.slice(originalBoundary.indexOf(priorTail));
const helperEnd='describe(';
const newImports=["import { invalidateCache, write } from '@/config/versionedStore';\n","import { CONTENT_KIND, SLOTS_KIND, LEARN_KIND } from '@/content/kinds';\n","import { invalidateLiftCache } from '@/content/service';\n"];
let prefix=currentBoundary.slice(0,currentBoundary.indexOf(helperEnd));for(const i of newImports)prefix=prefix.replace(i,'');
const helperUnchanged=prefix===originalBoundary.slice(0,originalBoundary.indexOf(helperEnd));
console.log(JSON.stringify({at:new Date().toISOString(),node:process.version,options,inputCount:inputs.length,expectedGraphCount:w.graph_input_count,uncovered,inputs,mismatches,originalCheck,protectedHistoricalPinsChecked:old.files.filter(f=>!originalPaths.has(f.path)).length,protectedDrift,originalBoundaryTailUnchanged:tailUnchanged,originalBoundaryHelpersUnchanged:helperUnchanged},null,2));
if(uncovered.length||mismatches.length||inputs.length!==w.graph_input_count||originalCheck.some(f=>f.expected!==f.actual)||protectedDrift.length||!tailUnchanged||!helperUnchanged)process.exitCode=1;
NODE
